<?php namespace App\Http\Controllers\Api\V1; use Illuminate\Http\Request; use App\Models\Message; class MessageController extends Controller {public function index(Request $r){$u=$r->user();$q=Message::where('school_id',$u->school_id)->where(fn($x)=>$x->where('sender_id',$u->id)->orWhere('receiver_id',$u->id));return $this->ok($q->orderByDesc('created_at')->paginate(50));}public function store(Request $r){$d=$r->validate(['receiver_id'=>'required|integer','message'=>'required|string|max:10000']);$d['school_id']=$r->user()->school_id;$d['sender_id']=$r->user()->id;$m=Message::create($d);return $this->ok($m,'Message sent',201);}}
